pub struct Invoice { id: InvoiceId, lines: Vec<Line>, currency: Currency }  // fields private

impl Invoice {
    pub fn add_line(&mut self, line: Line) -> Result<(), CurrencyError> {
        if line.currency != self.currency { return Err(CurrencyError); }
        self.lines.push(line);
        Ok(())
    }
    pub fn total(&self) -> Money { self.lines.iter().map(Line::amount).sum() }
}
